rows[144798]={title={{19,712263831},"강철의 별 폭발"},description={"^the impact of the iron star causes it to explode, inflicting ([%+%-]?%d[%d,.%+%-to –]*) fire damage to nearby enemies%. the damage inflicted decreases the farther away an enemy is from the explosion%.$","강철의 별이 충돌하면 폭발하며 주위의 모든 적에게 \0311\031의 화염 피해를 입힙니다. 폭발에서 멀리 떨어질수록 피해가 감소합니다.",{0},{1}}}
rows[144800]={title={{15,843301637},"자아성찰"},description={{261,1426633159},"교만의 샤가 교만의 투영체를 만들어내 최대 5명의 플레이어가 자신을 되돌아보도록 만듭니다. 자아성찰이 발동될 때마다 샤는 교만 수치가 더 높은 플레이어에게 집중해 교만 수치가 25 이상, 50 이상, 그리고 75 이상인 플레이어만을 목표로 삼습니다."}}
