rows[145065]={title={{17,1420130511},"이샤라즈의 손길"},description={{202,1909392810},"이샤라즈의 손길이 대상의 정신을 지배해 주위에 있는 또 다른 아군을 찾아 현혹하도록 만듭니다. 정신을 지배당한 대상에게 피해를 충분히 입히면 이 효과가 사라집니다."},aura={{39,1162187768},"이샤라즈의 손길을 퍼뜨리려고 함"}}
rows[145066]={title={{10,250306878},"투영"},description={"^causes an enemy's pride to project at a nearby location%. the projection explodes, inflicting ([%+%-]?%d[%d,.%+%-to –]*) shadow damage to all players after 8 seconds unless the creator of the projection is standing within it%.$","적의 교만을 주위 위치에 투영하게 만듭니다. 투영을 만들어낸 대상이 그 안에 서 있지 않으면 8초 후에 투영이 폭발해 모든 플레이어에게 \0311\031의 암흑 피해를 입힙니다.",{0},{1}}}
rows[145067]={title={{9,1350354670},"악령 퇴치"},description={"^the power of the light compels a humanoid, beast, undead, aberration, or demon target to flee for up to ([%+%-]?%d[%d,.]* %a+)%. only one target can be turned at a time%.$","빛의 힘으로 인간형, 야수, 언데드, 돌연변이 또는 악마를 최대 \0311\031 동안 달아나게 만듭니다. 한 번에 한 대상만 퇴치할 수 있습니다.",{1},{1}},aura={{18,1045907324},"퇴치 당해 도망 중"}}
