rows[145072]={title={{27,771586547},"아이템 - 흑마법사 T16 2P 보너스"},description={"^conflagrate critical strikes have a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to increase the critical strike chance of immolate and incinerate by ([%+%-]?%d[%d,.%+%-to –]*)%%%. unstable affliction critical hits have a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to increase all damaging effects of malefic grasp and drain soul by ([%+%-]?%d[%d,.%+%-to –]*)%% for ([%+%-]?%d[%d,.]* %a+)%. soul fire has a ([%+%-]?%d[%d,.%+%-to –]*)%% chance to increase you and your pet's damage dealt by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","점화 주문이 극대화 효과를 발휘하면, \0311\031%의 확률로 제물과 소각의 극대화율을 \0312\031%만큼 증가시킵니다. 불안정한 고통이 극대화 효과를 발휘하면, \0313\031%의 확률로 \0315\031 동안 재앙의 손아귀와 영혼 흡수로 적에게 입히는 모든 피해를 \0314\031%만큼 증가시킵니다. 영혼의 불꽃이 \0311\031%의 확률로 흑마법사와 소환수의 공격력을 \0311\031%만큼 증가시킵니다.",{0,0,0,0,1,0,0},{1,2,3,4,5,1,1}}}
