rows[145416]={title={{7,38485731},"독살"},description={"^finishing move that deals instant nature damage proportional to the number of combo points on the target%. following the envenom attack, your poison application chance is increased by ([%+%-]?%d[%d,.%+%-to –]*)%%, for 1 sec plus an additional 1 sec per combo point%.$","적에게 마무리 일격을 날려 즉시 연계 점수에 비례하는 자연 피해를 입힙니다. 독살 공격 후 연계 점수당 1초에 추가로 1초 동안 대상이 독에 감염될 확률이 \0311\031%만큼 증가합니다.",{0},{1}},aura={"^poison application chance increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","독을 감염시킬 확률 \0311\031%만큼 증가",{0},{1}}}
