rows[145529]={title={{22,631631080},"문양: 꽃피우기"},description={"^the efflorescence effect is now caused by your wild mushroom instead of by swiftmend, and lasts as long as the wild mushroom is active%. additionally, increases the healing done by swiftmend by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","꽃피우기 효과가 신속한 치유가 아닌 야생 버섯으로 발동되며, 야생 버섯이 활성화되어 있는 동안 지속됩니다. 추가로, 신속한 치유의 치유량이 \0311\031% 증가합니다.",{0},{1}}}
