rows[145532]={title={{10,1966086066},"얼음 회오리"},description={"^blasts enemies within ([%+%-]?%d[%d,.%+%-to –]*) yds of the caster for ([%+%-]?%d[%d,.%+%-to –]*) frost damage and freezes them in place for up to ([%+%-]?%d[%d,.]* %a+)%. damage caused may interrupt the effect%.$","반경 \0311\031미터 내의 적을 냉기로 강타하여 \0312\031의 냉기 피해를 입히고, 최대 \0313\031 동안 그 자리에 얼어붙게 만듭니다. 대상이 피해를 입으면 효과가 해제될 수 있습니다.",{0,0,1},{1,2,3}},aura={{16,147316927},"얼어붙음"}}
rows[145533]={title={{9,1960685663},"얼음 방패"},description={"^you become encased in a block of ice, protecting you from all physical attacks and spells for ([%+%-]?%d[%d,.]* %a+), but during that time you cannot attack, move or cast spells%.$","커다란 얼음 덩어리에 둘러싸여 \0311\031 동안 모든 물리 공격과 주문으로부터 보호받습니다. 하지만 이 동안은 공격하거나 이동하거나 마법을 사용하지 못합니다.",{1},{1}},aura={{68,56642901},"모든 공격 및 주문에 면역\010공격, 이동, 주문 사용 불가"}}
rows[145534]={title={{9,1522494438},"시간 왜곡"},description={"^warp the flow of time, increasing melee, ranged, and spell haste by ([%+%-]?%d[%d,.%+%-to –]*)%% for all party and raid members%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","시간의 흐름을 왜곡하여 모든 파티원과 공격대원의 근접, 원거리, 주문 가속을 \0311\031%만큼 증가시킵니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^melee, ranged, and spell haste increased by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","근접, 원거리, 주문 가속 \0311\031%만큼 증가",{0},{1}}}
rows[145535]={title={{5,1188315097},"점멸"},description={"^teleports the caster ([%+%-]?%d[%d,.%+%-to –]*) yards forward, unless something is in the way%. also frees the caster from stuns and bonds%.$","시전자를 기절시키거나 구속하는 모든 것에서 벗어나 전방으로 \0311\031미터 순간이동합니다. 경로에 장애물이 없어야 합니다.",{0},{1}},aura={{9,2046225448},"점멸 중"}}
