rows[145861]={title={{13,589958807},"자기몰입"},description={"^fills the target with vanity, causing them to admire their physique and ignore everything else%. stuns the target for ([%+%-]?%d[%d,.]* %a+)%.$","대상의 마음을 자만심으로 가득 채워, 자신의 몸매에 감탄하며 다른 모든 존재를 무시하도록 만듭니다. 대상을 \0311\031 동안 기절시킵니다.",{1},{1}},aura={{41,850334038},"자신의 잘생긴 외모에 사로잡힘. 기절함."}}
