rows[146804]={title={{8,1425314683},"포만감"},description={"^strength increased by ([%+%-]?%d[%d,.%+%-to –]*)%. melee attacks will also be significantly bloodier, even mysteriously against opponents with no blood%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","힘이 \0311\031만큼 증가합니다. 근접 공격 시 유혈 효과가 크게 증가합니다. 원래 피를 안 흘리는 대상에게도 그 효과가 신기하게 적용됩니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^strength increased by ([%+%-]?%d[%d,.%+%-to –]*)%. melee attacks are now also significantly bloodier, even mysteriously against opponents with no blood%.$","힘 \0311\031만큼 증가\010근접 공격 시 유혈 효과 크게 증가\010원래피를 안 흘리는 대상에게도 그 효과가 신기하게 적용됨",{0},{1}}}
rows[146805]={title={{8,1425314683},"포만감"},description={"^agility increased by ([%+%-]?%d[%d,.%+%-to –]*)%. melee and ranged attacks will also take on mysterious cosmetic properties%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","민첩성이 \0311\031만큼 증가합니다. 근접 및 원거리 공격의 외형에 신기한 변화가 일어납니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^agility increased by ([%+%-]?%d[%d,.%+%-to –]*)%. melee and ranged attacks have also taken on mysterious properties%.$","민첩성 \0311\031만큼 증가\010근접 및 원거리 공격의 외형에 신기한 변화 일어남",{0},{1}}}
rows[146806]={title={{8,1425314683},"포만감"},description={"^intellect increased by ([%+%-]?%d[%d,.%+%-to –]*)%. spell casts will also trigger cosmetic sparks that streak towards the intended targets%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","지능이 \0311\031만큼 증가합니다. 주문 시전 시 지정한 대상을 향해 이어지는 눈요기용 불꽃이 발동됩니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^intellect increased by ([%+%-]?%d[%d,.%+%-to –]*)%. spell casts have taken on some extra flare%.$","지능 \0311\031만큼 증가\010주문 시전 시 추가 불꽃 효과",{0},{1}}}
rows[146807]={title={{8,1425314683},"포만감"},description={"^spirit increased by ([%+%-]?%d[%d,.%+%-to –]*)%. your benificial spell effects will now also trigger cosmetic sparks that streak towards the intended targets%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","정신력이 \0311\031만큼 증가합니다. 이로운 주문 사용 시 장식용 불꽃이 지정된 대상을 향해 이어지는 효과가 발동됩니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^spirit increased by ([%+%-]?%d[%d,.%+%-to –]*)%. benificial spell effects have taken on some extra flare%.$","정신력 \0311\031만큼 증가\010이로운 주문 효과에 불꽃 추가",{0},{1}}}
rows[146808]={title={{8,1425314683},"포만감"},description={"^stamina increased by ([%+%-]?%d[%d,.%+%-to –]*)%. taking damage will now also cause you to appear larger and more stone%-like%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","체력이 \0311\031만큼 증가합니다. 피해를 입으면 몸이 더 커지고 바위처럼 보입니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^stamina increased by ([%+%-]?%d[%d,.%+%-to –]*)%. taken on a very stone%-like appearance%.$","체력 \0311\031만큼 증가\010외형이 바위처럼 변화",{0},{1}}}
rows[146809]={title={{8,1425314683},"포만감"},description={"^mastery increased by ([%+%-]?%d[%d,.%+%-to –]*)%. taking damage will now also cause you to appear larger and chillier%. lasts ([%+%-]?%d[%d,.]* %a+)%.$","특화가 \0311\031만큼 증가합니다. 피해를 입으면 자신의 모습이 더 커지고 더 차가워집니다. \0312\031 동안 지속됩니다.",{0,1},{1,2}},aura={"^mastery increased by ([%+%-]?%d[%d,.%+%-to –]*)%.$","특화 \0311\031만큼 증가",{0},{1}}}
