rows[148375]={title={{17,1213564677},"지독한 과다출혈"},description={"^inflicts ([%+%-]?%d[%d,.%+%-to –]*)%% of the target's health as physical damage and ([%+%-]?%d[%d,.%+%-to –]*) every ([%+%-]?%d[%d,.%+%-to –]*) sec for ([%+%-]?%d[%d,.]* %a+)%. in addition, healing upon the target is reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","대상의 가진 생명력의 \0311\031%에 해당하는 물리 피해를 입히고 \0314\031 동안 \0313\031초마다 \0312\031의 피해를 입힙니다. 추가로 대상이 받는 치유 효과를 \0315\031%만큼 감소시킵니다.",{0,0,0,1,0},{1,2,3,4,5}},aura={"^suffering ([%+%-]?%d[%d,.%+%-to –]*) physical damage every ([%+%-]?%d[%d,.%+%-to –]*) sec%. healing taken reduced by ([%+%-]?%d[%d,.%+%-to –]*)%%%.$","\0312\031초마다 \0311\031의 물리 피해\010받는 치유 효과 \0313\031%만큼 감소",{0,0,0},{1,2,3}}}
rows[148385]={title={{23,1180963289},"영원한 고통의 향로"},description={"^sacrifice ([%+%-]?%d[%d,.%+%-to –]*)%% of maximum health to become an emissary of ordos%. while transformed, you are hostile to all players, and killing players grants bloody coins%. can only be used on the timeless isle, and flags the user for pvp%.$","최대 생명력의 \0311\031%를 희생해 오르도스의 사절이 됩니다. 변신 중에는 모든 플레이어에게 적대적이 되며 플레이어 처치 시 피투성이 동전을 얻습니다. 영원의 섬에서만 사용할 수 있으며, 사용자는 PvP 상태가 됩니다.",{0},{1}},aura={{105,119491834},"모든 플레이어에게 적대적\010\010|cFFFFAA00\"영원히 타오르는 오르도스의 불꽃이 화염의 제물에 굶주렸습니다.\"|r"}}
